using System;using System.IO;using SlopStudio;
internal static class PluginChainIntegrationTests{
 static int Main(string[] args){try{string root=args[0];foreach(string format in new[]{"VST3","CLAP"}){string path=Path.Combine(root,format,"Vital."+format.ToLower());PluginDescriptor descriptor=NativePlugin.Scan(path)[0];if(!descriptor.Instrument)throw new Exception("Vendor instrument classification failed.");ProjectDocument p=new ProjectDocument{Name="Vendor instrument"};Track t=ProjectFactory.CreateTrack("Vital",TrackType.Midi);t.Plugins.Add(descriptor.CreateSlot());Region r=ProjectFactory.CreateRegion("Notes",0,4);r.Notes.Add(new MidiNote{StartBeat=0,LengthBeats=2,Pitch=60,Velocity=100});t.Regions.Add(r);p.Tracks.Add(t);AppSettings settings=new AppSettings{SampleRate=48000,BufferFrames=512};using(ArrangementEngine engine=new ArrangementEngine(settings)){float[] audio=engine.RenderOffline(p,8192,0);float peak=0;foreach(float value in audio){if(Single.IsNaN(value)||Single.IsInfinity(value))throw new Exception("Invalid PCM.");peak=Math.Max(peak,Math.Abs(value));}if(peak<0.001||engine.Warnings.Count>0)throw new Exception("App instrument graph did not produce valid audio: "+String.Join("; ",engine.Warnings.ToArray())+" peak="+peak);engine.CapturePluginStates();string state=p.Tracks[0].Plugins[0].State;if(String.IsNullOrEmpty(state))throw new Exception("Vendor state was not captured.");ProjectDocument reopened=ProjectFile.Deserialize(ProjectFile.Serialize(p));engine.ResetProject();audio=engine.RenderOffline(reopened,8192,0);peak=0;foreach(float value in audio)peak=Math.Max(peak,Math.Abs(value));if(peak<0.001||engine.Warnings.Count>0)throw new Exception("Restored app instrument graph failed.");Console.WriteLine("PASS installed Vital "+format+": app arrangement engine, instrument classification, MIDI routing, real PCM, state capture, .slopdaw round-trip, graph recreation and unload; restored peak="+peak);}}return 0;}catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}}
}
